import zipfile
import xml.etree.ElementTree as ET

NS = {
    'm': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
    'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'
}

path = 'budget.xlsx'
with zipfile.ZipFile(path) as z:
    names = z.namelist()
    print("Archive entries:")
    for n in names:
        print("  ", n)

    # workbook.xml -> sheets and relationships
    wb_tree = ET.fromstring(z.read('xl/workbook.xml'))
    rels_tree = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    rels = {}
    for rel in rels_tree.findall('{http://schemas.openxmlformats.org/package/2006/relationships}Relationship'):
        rels[rel.get('Id')] = rel.get('Target')

    sheets = []
    for sh in wb_tree.find('m:sheets', NS):
        sheets.append((sh.get('name'), sh.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')))
    print("\nSheets in workbook:", sheets)

    # shared strings
    shared = []
    if 'xl/sharedStrings.xml' in names:
        ss_tree = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in ss_tree.findall('m:si', NS):
            text = ''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
            shared.append(text)
    print("\nShared strings:", shared)

    for sheet_name, rid in sheets:
        target = rels.get(rid)
        if target.startswith('/'):
            target = target.lstrip('/')
        else:
            target = 'xl/' + target
        print(f"\n=== Sheet: {sheet_name} (target {target}) ===")
        sheet_tree = ET.fromstring(z.read(target))
        for row in sheet_tree.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}row'):
            for c in row:
                ref = c.get('r')
                t = c.get('t')
                v = c.find('m:v', NS)
                is_val = c.find('m:is', NS)
                val = None
                if v is not None and v.text is not None:
                    val = v.text
                    if t == 's':
                        val = shared[int(val)]
                elif is_val is not None:
                    val = ''.join(x.text or '' for x in is_val.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
                if val is not None:
                    print(f"  {ref}: {val!r}")

import sys
import zipfile
import re
import xml.etree.ElementTree as ET

NS = {"m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main"}

path = "budget.xlsx"
try:
    z = zipfile.ZipFile(path)
except Exception as e:
    print(f"ERROR opening {path}: {e}")
    sys.exit(1)

names = z.namelist()
print("ARCHIVE ENTRIES:", names)

# Shared strings
shared = []
if "xl/sharedStrings.xml" in names:
    root = ET.fromstring(z.read("xl/sharedStrings.xml"))
    for si in root.findall("m:si", NS):
        text = "".join(t.text or "" for t in si.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
        shared.append(text)

# Workbook sheet names -> r:id mapping
sheet_map = {}
if "xl/workbook.xml" in names:
    wbroot = ET.fromstring(z.read("xl/workbook.xml"))
    for sh in wbroot.findall("m:sheets/m:sheet", NS):
        sheet_map[sh.get("name")] = sh.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id")

# relationships
rels = {}
if "xl/_rels/workbook.xml.rels" in names:
    rroot = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
    for rel in rroot:
        rels[rel.get("Id")] = rel.get("Target")

def col_to_idx(ref):
    letters = re.match(r"[A-Z]+", ref).group(0)
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - 64)
    return idx

total = 0.0
for name, rid in sheet_map.items():
    target = rels.get(rid, "")
    if not target.startswith("xl/"):
        target = "xl/" + target.lstrip("/")
    if target not in names:
        print(f"WARN: sheet file {target} not found")
        continue
    sroot = ET.fromstring(z.read(target))
    print(f"\n--- Sheet: {name} ---")
    for row in sroot.findall(".//m:sheetData/m:row", NS):
        rnum = row.get("r")
        for c in row.findall("m:c", NS):
            ref = c.get("r")
            t = c.get("t")
            v = c.find("m:v", NS)
            val = v.text if v is not None else None
            if t == "s" and val is not None:
                val = shared[int(val)]
            elif val is not None and t != "s":
                try:
                    val = float(val)
                except ValueError:
                    pass
            if val is not None:
                print(f"  {ref}: {val!r}")
                if isinstance(val, float):
                    total += val

print(f"\nTOTAL EXPENSES (all categories): {total}")

